mapper.update:
UPDATE product_stock
SET quantity = quantity + #{changeQty}
WHERE product_code = #{productCode}
  AND quantity + #{changeQty} >= 0

mapper.select:
SELECT stock_history_id AS historyId,product_code AS productCode,type AS historyType,quantity,balance_after AS balanceAfter,
       memo,created_by AS createdBy,created_at AS createdAt,cancel_yn AS cancelYn,cancelled_by AS cancelledBy,cancelled_at AS cancelledAt
FROM product_stock_history WHERE stock_history_id=#{historyId}

SELECT user_id AS userId, username, password_hash AS passwordHash,
       display_name AS displayName, role, use_yn AS useYn, created_at AS createdAt
FROM app_user WHERE username = #{username}

mapper.update:
UPDATE sales_order SET order_status=CASE WHEN shipped_qty >= ordered_qty THEN 'SHIPPED'
    WHEN shipped_qty > 0 THEN 'PARTIAL_SHIPMENT' WHEN produced_qty >= ordered_qty THEN 'READY'
    WHEN produced_qty > 0 THEN 'PRODUCTION' ELSE 'ORDERED' END WHERE order_id=#{orderId}

UPDATE sales_order SET customer_id=#{customerId},product_code=#{productCode},ordered_qty=#{orderedQty},produced_qty=#{producedQty},defective_qty=#{defectiveQty},shipped_qty=#{shippedQty},unit_price=#{unitPrice},
    total_amount=#{totalAmount},order_date=#{orderDate},due_date=#{dueDate},memo=#{memo},updated_by=#{updatedBy},updated_at=NOW()
WHERE order_id=#{orderId} AND order_status!='CANCELLED' AND #{orderedQty} >= #{producedQty} AND #{orderedQty} >= #{shippedQty} AND #{producedQty} >= #{shippedQty}
